import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createServer } from 'vite';

// The approved drawing is an independent fixture, not regenerated by this test.
const drawing = await readFile(new URL('../docs/seating-approved.svg', import.meta.url), 'utf8');
const server = await createServer({ server: { middlewareMode: true }, appType: 'custom' });
try {
  const { TABLES, GEOM, HALL, layoutFor, seatPos, seatKey, seatPrice } = await server.ssrLoadModule('/src/data/seating.ts');
  assert.equal(TABLES.length, 15);
  const keys = new Set();
  const vertical = layoutFor('v');
  const horizontal = layoutFor('h');
  const drawnCenter = (n) => drawing.split(`<g id="table-${n}" data-table="${n}">`)[1]
    .match(/<circle cx="([\d.]+)" cy="([\d.]+)"/).slice(1).map(Number);
  const anchor = TABLES.find((t) => t.n === 14);
  const other = TABLES.find((t) => t.n === 15);
  const anchorRef = drawnCenter(14);
  const otherRef = drawnCenter(15);
  const scale = (other.x - anchor.x) / (otherRef[0] - anchorRef[0]);
  assert.ok(Math.abs(scale - (other.y - anchor.y) / (otherRef[1] - anchorRef[1])) < 1e-8);
  for (const tb of TABLES) {
    const group = drawing.split(`<g id="table-${tb.n}" data-table="${tb.n}">`)[1];
    assert.ok(group, `Approved table ${tb.n}`);
    const center = group.match(/<circle cx="([\d.]+)" cy="([\d.]+)"/).slice(1).map(Number);
    assert.ok(Math.abs(tb.x - anchor.x - (center[0] - anchorRef[0]) * scale) < 1e-8, `Approved table ${tb.n} x`);
    assert.ok(Math.abs(tb.y - anchor.y - (center[1] - anchorRef[1]) * scale) < 1e-8, `Approved table ${tb.n} y`);
    let sweep = 0;
    let previous;
    for (let seat = 1; seat <= 8; seat++) {
      const label = group.split(`<g id="table-${tb.n}-seat-${seat}" data-seat="${seat}">`)[1];
      assert.ok(label, `Approved chair ${tb.n}-${seat}`);
      const ref = label.match(/<text x="([\d.]+)" y="([\d.]+)"/).slice(1).map(Number);
      const pos = seatPos(tb, seat);
      const dx = pos.x - tb.x;
      const dy = pos.y - tb.y;
      assert.ok(Math.abs(dx - (ref[0] - center[0]) * GEOM.orbit / 50) < 1e-8, `Chair ${tb.n}-${seat} approved x`);
      assert.ok(Math.abs(dy - (ref[1] - center[1]) * GEOM.orbit / 50) < 1e-8, `Chair ${tb.n}-${seat} approved y`);
      const rotatedTable = horizontal.tables.find((t) => t.n === tb.n);
      const rotated = seatPos(rotatedTable, seat, 'h');
      const [x, y] = horizontal.pt(pos.x, pos.y);
      assert.ok(Math.abs(rotated.x - x) < 1e-8 && Math.abs(rotated.y - y) < 1e-8, `${tb.n}-${seat} rotates with hall`);
      assert.ok(Math.abs(rotated.rot - (pos.rot - 90)) < 1e-8);
      const [vx, vy] = vertical.pt(pos.x, pos.y);
      assert.equal(vx, pos.x);
      assert.equal(vy, pos.y);
      assert.ok(pos.x > HALL.x + GEOM.seatW && pos.x < HALL.x + HALL.w - GEOM.seatW);
      assert.ok(pos.y > HALL.y + GEOM.seatW && pos.y < HALL.y + HALL.h - GEOM.seatW);
      const angle = Math.atan2(dy, dx);
      if (previous !== undefined) sweep += (angle - previous + Math.PI * 2) % (Math.PI * 2);
      previous = angle;
      keys.add(seatKey(tb.n, seat));
    }
    // Exactly one clockwise occupied arc, with an intentional empty sector.
    assert.ok(sweep < Math.PI * 2 && sweep > Math.PI, `Table ${tb.n} clockwise numbering`);
    assert.equal(seatPrice(tb.n), tb.n <= 2 ? 20000 : [3, 4, 8, 10].includes(tb.n) ? 17000 : 15000);
  }
  assert.equal(keys.size, 120);
  assert.deepEqual([...keys].sort(), Array.from({ length: 15 }, (_, t) => Array.from({ length: 8 }, (_, s) => `${t + 1}-${s + 1}`)).flat().sort());
  console.log('Seating: 120 approved chairs, stable booking keys and prices, both orientations passed');
} finally {
  await server.close();
}
